buggy.described_examples:
import os, inspect, traceback

info = {}

# Locate any file mentioning scalar_atomic
hits = []
for root, dirs, files in os.walk('.'):
    dirs[:] = [d for d in dirs if d not in ('.git', '__pycache__', '.mypy_cache')]
    for fn in files:
        if not fn.endswith('.py'):
            continue
        p = os.path.join(root, fn)
        try:
            s = open(p, encoding='utf-8', errors='replace').read()
        except Exception:
            continue
        if 'scalar_atomic' in s:
            hits.append(p)
info['files_with_scalar_atomic'] = hits

# Source of the test, if found
try:
    if hits:
        p = hits[0]
        s = open(p, encoding='utf-8', errors='replace').read()
        idx = s.find('scalar_atomic')
        # find enclosing def by searching backwards
        start = s.rfind('\n  def ', 0, idx)
        start2 = s.rfind('\n  @', 0, idx)
        start = min([x for x in (start, start2) if x != -1] or [max(0, idx - 1500)])
        info['test_snippet'] = s[start:idx + 4000]
except Exception as e:
    info['test_snippet_err'] = traceback.format_exc()

# plgpu module
try:
    from jax.experimental.pallas import gpu as plgpu
    info['plgpu_file'] = getattr(plgpu, '__file__', None)
    info['atomic_names'] = [n for n in dir(plgpu) if 'atomic' in n.lower()]
    for nm in ('atomic_max', 'atomic_min'):
        try:
            info['src_' + nm] = inspect.getsource(getattr(plgpu, nm))
        except Exception as e:
            info['src_err_' + nm] = repr(e)
except Exception as e:
    info['plgpu_import_err'] = traceback.format_exc()

probe('explore', info)

